<?php

namespace Tests\Data;

use App\Data\DopplerRingSettings;
use App\Enums\HeroRingsMotion;
use Generator;
use PHPUnit\Framework\Attributes\CoversClass;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use PHPUnit\Framework\TestCase;

#[CoversClass(DopplerRingSettings::class)]
class DopplerRingSettingsTest extends TestCase
{
    #[Test]
    public function it_generates_the_same_rings_as_the_lab_for_a_seed(): void
    {
        $settings = DopplerRingSettings::defaults();

        // The homepage logo arrangement, as generated by the lab's JavaScript for seed 7
        $this->assertSame([
            [-0.488, -0.482], [0.199, 0.024], [-0.034, -0.286], [0.23, -0.266],
            [0.264, 0.02], [-0.132, -0.227], [-0.204, 0.526], [0.378, -0.34],
        ], $settings->perRing());
    }

    public static function clampProvider(): Generator
    {
        yield 'above the maximum' => ['mach', 99, 3.0];
        yield 'below the minimum' => ['rings', 0, 2];
        yield 'not a number' => ['reach', 'wide', 300];
    }

    #[Test]
    #[DataProvider('clampProvider')]
    public function it_keeps_values_within_their_slider_range(string $key, mixed $value, int|float $expected): void
    {
        $settings = DopplerRingSettings::fromArray([$key => $value]);

        $this->assertEquals($expected, $settings->{$key});
    }

    #[Test]
    public function it_keeps_the_scroll_end_after_the_start(): void
    {
        $settings = DopplerRingSettings::fromArray(['scrollStart' => 1, 'scrollEnd' => 0.5]);

        $this->assertGreaterThan(1, $settings->scrollEnd);
    }

    #[Test]
    public function it_round_trips_through_an_array(): void
    {
        $settings = DopplerRingSettings::fromArray(['mach' => 1.5, 'seed' => 42, 'motion' => HeroRingsMotion::Auto->value, 'travelLeft' => false]);

        $this->assertEquals($settings, DopplerRingSettings::fromArray($settings->toArray()));
    }
}
